"""APA-style statistical figures.

The core writes a standalone `figures.py` into the run folder and runs it in a
subprocess, like an engine script. Figures draw the data themselves (points,
boxes, distributions) and per-case values the engine already produced (e.g.
regression residuals); they never print test statistics or p values.
"""

from __future__ import annotations

import json

from .engines.base import fill_template

SCRIPT = '''\
#!/usr/bin/env python3
# Generated by aistat __AISTAT_VERSION__ for __RUN_ID__ (__METHOD__): APA-style figures.
# Re-run from this folder:  python figures.py [data.csv] [figures/figures.json]
import json
import os
import sys

import matplotlib

matplotlib.use("Agg")
import matplotlib.pyplot as plt
import numpy as np
import pandas as pd
from matplotlib import font_manager
from matplotlib.text import Text
from scipy import stats

PLAN = json.loads(__PLAN_JSON__)
DATA = sys.argv[1] if len(sys.argv) > 1 else __DEFAULT_DATA__
OUT = sys.argv[2] if len(sys.argv) > 2 else "figures/figures.json"
V, M = PLAN["variables"], PLAN["method"]
with open("raw_outputs/results.json", encoding="utf-8") as f:
    RESULTS = json.load(f)
S = RESULTS["statistics"]
df = pd.read_csv(DATA, encoding="utf-8", dtype={c: str for c in PLAN.get("string_columns", [])})
os.makedirs(os.path.dirname(OUT) or ".", exist_ok=True)

CJK_FONTS = ["Noto Sans CJK TC", "Noto Sans TC", "Noto Sans CJK JP", "Source Han Sans TC", "Microsoft JhengHei",
             "PingFang TC", "Heiti TC", "WenQuanYi Zen Hei", "SimHei", "Arial Unicode MS"]
available = {f.name for f in font_manager.fontManager.ttflist}
CJK = next((name for name in CJK_FONTS if name in available), None)
plt.rcParams.update({
    "font.family": "sans-serif",
    "font.sans-serif": ([CJK] if CJK else []) + ["DejaVu Sans"],
    "font.size": 10,
    "axes.spines.top": False,
    "axes.spines.right": False,
    "axes.unicode_minus": False,
    "figure.facecolor": "white",
    "savefig.facecolor": "white",
    "savefig.dpi": 300,
    "svg.hashsalt": "aistat",  # deterministic SVG ids
})
GREY, DARK = "#9e9e9e", "#212121"
figures = []
needs_cjk = False  # set when a drawn label (axis, tick, legend) has non-ASCII text


def save(fig, zh, en):
    global needs_cjk
    needs_cjk = needs_cjk or any(ord(ch) > 127 for t in fig.findobj(Text) for ch in t.get_text())
    n = len(figures) + 1
    base = os.path.join(os.path.dirname(OUT) or ".", f"figure_{n}")
    fig.tight_layout()
    fig.savefig(base + ".png")
    fig.savefig(base + ".svg", metadata={"Date": None})
    plt.close(fig)
    figures.append({"file": os.path.relpath(base, ".").replace(os.sep, "/"), "caption": {"zh": zh, "en": en}})


def jitter(n, width=0.08):
    return np.linspace(-width, width, n) if n > 1 else np.zeros(n)


def paired():
    b, a = V["before"], V["after"]
    d = df[[b, a]].dropna()
    fig, ax = plt.subplots(figsize=(4, 4))
    for x0, x1 in zip(d[b], d[a]):
        ax.plot([0, 1], [x0, x1], color=GREY, linewidth=0.8, alpha=0.7)
    if M == "paired-t-test":
        centre, label = [S["mean_before"], S["mean_after"]], "Mean"
    else:
        centre, label = [S["median_before"], S["median_after"]], "Median"
    ax.plot([0, 1], centre, color=DARK, linewidth=2.2, marker="o", label=label)
    ax.set_xticks([0, 1], [b, a])
    ax.set_xlim(-0.3, 1.3)
    ax.set_ylabel("Value")
    ax.legend(frameon=False)
    save(fig, f"同一受試者在 {b} 與 {a} 的分數（灰線為個人，黑線為{'平均數' if label == 'Mean' else '中位數'}）",
         f"Scores for {b} and {a} by participant (grey lines) with the {label.lower()} (black)")


def by_group():
    y, g = V["outcome"], V["group"]
    d = df[[y, g]].dropna()
    levels = PLAN["levels"][g]
    groups = [d.loc[d[g] == lvl, y].to_numpy(dtype=float) for lvl in levels]
    fig, ax = plt.subplots(figsize=(1.6 + 1.2 * len(levels), 4))
    ax.boxplot(groups, widths=0.5, showfliers=False, medianprops={"color": DARK},
               boxprops={"color": DARK}, whiskerprops={"color": DARK}, capprops={"color": DARK})
    for i, x in enumerate(groups, start=1):
        ax.scatter(i + jitter(len(x)), np.sort(x), s=14, color=GREY, zorder=3)
    ax.set_xticks(range(1, len(levels) + 1), levels)
    ax.set_xlabel(g)
    ax.set_ylabel(y)
    save(fig, f"各組 {y} 的箱形圖與個別觀察值（依 {g} 分組）",
         f"Box plots of {y} by {g}, with individual observations")


def contingency():
    r, c = V["row"], V["column"]
    props = np.array(S["row_proportions"])
    fig, ax = plt.subplots(figsize=(5.5, 1.2 + 0.6 * len(S["row_levels"])))
    left = np.zeros(len(S["row_levels"]))
    shades = plt.cm.Greys(np.linspace(0.35, 0.85, len(S["column_levels"])))
    for j, level in enumerate(S["column_levels"]):
        ax.barh(S["row_levels"], props[:, j], left=left, color=shades[j], edgecolor="white", label=level)
        left += props[:, j]
    ax.set_xlim(0, 1)
    ax.set_xlabel(f"Proportion within {r}")
    ax.set_ylabel(r)
    ax.legend(title=c, frameon=False, bbox_to_anchor=(1.02, 1), loc="upper left")
    save(fig, f"{r} 各類別中 {c} 的比例（堆疊長條圖）", f"Proportion of {c} within each level of {r}")


def scatter():
    x, y = V["x"], V["y"]
    d = df[[x, y]].dropna()
    fig, ax = plt.subplots(figsize=(4.5, 4))
    ax.scatter(d[x], d[y], s=18, color=DARK)
    ax.set_xlabel(x)
    ax.set_ylabel(y)
    save(fig, f"{x} 與 {y} 的散布圖", f"Scatter plot of {y} against {x}")


def regression():
    y, xs = V["outcome"], V["predictors"]
    diag = RESULTS.get("diagnostics") or {}
    fitted, resid = np.asarray(diag.get("fitted", []), float), np.asarray(diag.get("residuals", []), float)
    if len(xs) == 1:
        d = df[[y, xs[0]]].dropna()
        b0, b1 = S["coefficients"][0]["b"], S["coefficients"][1]["b"]
        fig, ax = plt.subplots(figsize=(4.5, 4))
        ax.scatter(d[xs[0]], d[y], s=18, color=DARK)
        grid = np.linspace(d[xs[0]].min(), d[xs[0]].max(), 50)
        ax.plot(grid, b0 + b1 * grid, color=GREY, linewidth=2)
        ax.set_xlabel(xs[0])
        ax.set_ylabel(y)
        save(fig, f"{xs[0]} 與 {y} 的散布圖與迴歸線", f"Scatter plot of {y} against {xs[0]} with the fitted regression line")
    fig, (ax1, ax2) = plt.subplots(1, 2, figsize=(8, 3.6))
    ax1.scatter(fitted, resid, s=16, color=DARK)
    ax1.axhline(0, color=GREY, linewidth=1)
    ax1.set_xlabel("Fitted values")
    ax1.set_ylabel("Residuals")
    (osm, osr), (slope, intercept, _) = stats.probplot(resid)
    ax2.scatter(osm, osr, s=16, color=DARK)
    ax2.plot(osm, slope * np.asarray(osm) + intercept, color=GREY, linewidth=1)
    ax2.set_xlabel("Theoretical quantiles")
    ax2.set_ylabel("Residual quantiles")
    save(fig, "殘差診斷：殘差對配適值（左）與殘差常態 Q-Q 圖（右）",
         "Residual diagnostics: residuals against fitted values (left) and normal Q-Q plot of residuals (right)")


def descriptives():
    names = V["variables"]
    numeric = [n for n in names if n not in PLAN["string_columns"]]
    categorical = [n for n in names if n in PLAN["string_columns"]]
    if numeric:
        fig, axes = plt.subplots(1, len(numeric), figsize=(3.2 * len(numeric), 3.2), squeeze=False)
        for ax, name in zip(axes[0], numeric):
            ax.hist(df[name].dropna().to_numpy(dtype=float), bins="auto", color=GREY, edgecolor="white")
            ax.set_xlabel(name)
            ax.set_ylabel("Count")
        save(fig, "數值變項的分布（直方圖）", "Distributions of numeric variables (histograms)")
    if categorical:
        summaries = {v["name"]: v for v in S["variables"]}
        fig, axes = plt.subplots(1, len(categorical), figsize=(3.2 * len(categorical), 3.2), squeeze=False)
        for ax, name in zip(axes[0], categorical):
            freqs = summaries[name]["frequencies"]
            ax.bar([str(f["level"]) for f in freqs], [f["count"] for f in freqs], color=GREY)
            ax.set_xlabel(name)
            ax.set_ylabel("Count")
        save(fig, "類別變項的次數（長條圖）", "Counts of categorical variables (bar charts)")


DRAW = {
    "paired-t-test": paired, "wilcoxon-signed-rank": paired,
    "independent-t-test": by_group, "mann-whitney-u": by_group, "one-way-anova": by_group,
    "chi-square": contingency, "fisher-exact": contingency,
    "correlation": scatter, "linear-regression": regression, "descriptives": descriptives,
}
DRAW[M]()
with open(OUT, "w", encoding="utf-8") as f:
    json.dump({"figures": figures, "cjk_font": CJK, "needs_cjk": needs_cjk}, f, ensure_ascii=False, indent=2)
'''


def render_script(plan: dict, default_data: str) -> str:
    return fill_template(SCRIPT, plan, PLAN_JSON=repr(json.dumps(plan, ensure_ascii=False)),
                         DEFAULT_DATA=repr(default_data))
